function pastePanel(){openPanel('Paste text',`<div class="paste-sheet"><label class="paste-tab"><span class="paste-tab-label">File name</span><input id="paste-name" class="paste-name" value="Untitled.md" autocomplete="off" autocapitalize="off" spellcheck="false"></label><label class="paste-page"><span class="sr-only">Markdown or plain text</span><textarea id="paste-body" class="paste-body" placeholder="# An idea worth keeping…"></textarea></label><div class="panel-actions"><button type="button" class="key key--text" data-close>Cancel</button><button type="button" class="key key--plate paste-open" data-action="save-paste"><span class="pip" aria-hidden="true"></span><span class="key-label">Open text</span></button></div></div>`,{size:'full'});$('#paste-body').addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();$('.paste-open')?.click();}});$('#paste-body').focus();}
