document.addEventListener('pointerdown',e=>{const lip=e.target.closest?.('.sheet-lip'),sheet=lip?.closest('dialog');if(!lip||!sheet?.open||!e.isPrimary)return;sheetDrag={sheet,id:e.pointerId,y:e.clientY,t:performance.now(),dy:0,v:0,h:sheet.getBoundingClientRect().height};try{lip.setPointerCapture(e.pointerId);}catch{}sheet.style.transition='none';});
document.addEventListener('pointermove',e=>{if(!sheetDrag||e.pointerId!==sheetDrag.id)return;const now=performance.now(),dy=Math.max(0,e.clientY-sheetDrag.y);sheetDrag.v=(dy-sheetDrag.dy)/Math.max(1,now-sheetDrag.t);sheetDrag.dy=dy;sheetDrag.t=now;sheetDrag.sheet.style.transform=`translateY(${dy}px)`;},{passive:true});
for(const type of ['pointerup','pointercancel'])document.addEventListener(type,e=>{if(!sheetDrag||e.pointerId!==sheetDrag.id)return;const {sheet,v,dy,h}=sheetDrag;sheetDrag=null;sheet.style.transition='';if(type==='pointerup'&&(v>.6||dy>h*.4)){feedback();sheet.close();sheet.style.transform='';}else sheet.style.transform='';});
document.addEventListener('pointermove',e=>{if(press&&e.pointerId===press.id&&Math.hypot(e.clientX-press.x,e.clientY-press.y)>12)releasePress();},{passive:true});
for(const type of ['pointerup','pointercancel','lostpointercapture'])document.addEventListener(type,releasePress);window.addEventListener('blur',releasePress);document.addEventListener('scroll',releasePress,{passive:true,capture:true});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[role="button"][data-action]')){e.preventDefault();e.target.click();}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch();}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='f'&&state.view==='reader'){e.preventDefault();showFind();}if(e.key==='Escape'&&state.focus&&!document.querySelector('dialog[open]'))actions.focus();});
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
window.addEventListener('native-library',e=>receiveLibrary(e.detail));window.addEventListener('native-error',e=>toast(e.detail));window.addEventListener('native-message',e=>toast(e.detail));window.addEventListener('native-busy',e=>busy(e.detail));
window.Nightwire={debug:{navigate,openDocument,preferences,more,typefaces,openSearch,loadSamples,state:()=>state,settings:(patch={})=>{Object.assign(state.settings,patch);applySettings();return {...state.settings};}},savePosition,pauseReading:()=>terminal?.pause(),back(){if(terminal?.exitBlackout())return true;if(document.querySelector('dialog[open]')){closePanels();return true;}if($('#find-input')){closeFind();return true;}if(state.focus){actions.focus();return true;}if(state.view==='reader'){navigate(state.returnTo||'library');return true;}if(state.view==='graph'&&state.doc&&state.docs.some(d=>d.id===state.doc.id)){openDocument(state.doc.id);return true;}if(state.view!=='home'){navigate('home');return true;}return false;},classifiers:new ClassifierRegistry(),async classifierInput(id=state.active){const d=state.docs.find(v=>v.id===id);if(!d)throw Error('Choose a document first');const text=await getText(d),a=C.analyze(text,d.name,md);const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text));const hash=[...new Uint8Array(digest)].map(b=>b.toString(16).padStart(2,'0')).join('');return {schemaVersion:1,documentId:d.id,contentRevision:hash,name:d.name,title:a.title,text,headings:a.headings,tags:a.tags};}};
// E5 (§6.6), runs once: Literata is the default reading face, so a stored 'sans' from before typeV2 moves to it. "System sans" stays in the Type case.
function migrateSettings(){const s=state.settings;if(s.typeV2)return;if(s.font==='sans')s.font='literata';s.typeV2=true;}
migrateSettings();applySettings();render();
if(native)Native.list();else try{database=await initDB();await receiveLibrary({docs:(await dbAll()).map(({text,...d})=>d)});}catch(e){toast('Local storage is unavailable: '+e.message);}
